'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import type { VendorDetail, VendorStatus } from '@/lib/admin/vendors'

const statusActions: Array<{ status: VendorStatus; label: string; consequence: string }> = [
  { status: 'active', label: 'Activate', consequence: 'This vendor can use capabilities allowed for active accounts.' },
  { status: 'suspended', label: 'Suspend', consequence: 'Vendor operations should be blocked while preserving records and history.' },
  { status: 'inactive', label: 'Deactivate', consequence: 'The vendor will be inactive and retained for historical reporting.' },
  { status: 'rejected', label: 'Reject', consequence: 'The vendor will be marked rejected. No records will be deleted.' },
  { status: 'onboarding', label: 'Move to onboarding', consequence: 'The vendor will return to the onboarding lifecycle.' },
]
function label(value: string) { return value.replaceAll('_', ' ') }
function formatDate(value: string) { return new Intl.DateTimeFormat('en', { dateStyle: 'medium' }).format(new Date(value)) }

export default function AdminVendorDetailPage({ params }: { params: Promise<{ vendorId: string }> }) {
  const [vendorId, setVendorId] = useState(''); const [vendor, setVendor] = useState<VendorDetail | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [pending, setPending] = useState<typeof statusActions[number] | null>(null); const [reason, setReason] = useState(''); const [message, setMessage] = useState('')
  useEffect(() => { void params.then(({ vendorId: currentId }) => setVendorId(currentId)) }, [params])
  useEffect(() => { if (!vendorId) return; void fetch(`/api/admin/vendors/${vendorId}`).then(async (response) => { const data = await response.json() as VendorDetail & { error?: string }; if (!response.ok) throw new Error(data.error || 'Unable to load vendor.'); setVendor(data) }).catch((loadError: unknown) => setError(loadError instanceof Error ? loadError.message : 'Unable to load vendor.')).finally(() => setLoading(false)) }, [vendorId])
  async function changeStatus() { if (!vendor || !pending) return; const response = await fetch(`/api/admin/vendors/${vendor.id}/status`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: pending.status, reason }) }); const data = await response.json() as { error?: string }; if (!response.ok) { setError(data.error || 'Unable to change vendor status.'); return } setVendor({ ...vendor, status: pending.status }); setMessage(`Vendor status changed to ${label(pending.status)}.`); setPending(null); setReason('') }
  if (loading) return <main className="admin-page"><div className="admin-shell"><p className="admin-empty">Loading vendor...</p></div></main>
  if (error || !vendor) return <main className="admin-page"><div className="admin-shell"><div className="admin-config-notice admin-config-error">{error || 'Vendor not found.'}</div><Link href="/admin/vendors" className="admin-button admin-button-secondary">Back to vendors</Link></div></main>
  return <main className="admin-page"><header className="admin-header"><Link href="/admin/vendors" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/admin" className="admin-nav-link">Dashboard</Link><Link href="/admin/vendors" className="admin-nav-link">Vendors</Link><span className="admin-role-chip">Detail</span></nav></header><div className="admin-shell"><section className="admin-hero admin-hero-compact"><div><p className="admin-eyebrow">Vendor record</p><h1>{vendor.name}</h1><p>{vendor.email || 'No vendor email recorded'} · Created {formatDate(vendor.createdAt)}</p></div><div className="admin-detail-status"><span className={`admin-status admin-status-${vendor.status}`}>{label(vendor.status)}</span><select aria-label="Vendor status actions" value="" onChange={(event) => { const action = statusActions.find((item) => item.status === event.target.value); if (action) setPending(action) }}><option value="">Change status...</option>{statusActions.filter((action) => action.status !== vendor.status).map((action) => <option value={action.status} key={action.status}>{action.label}</option>)}</select></div></section>{message ? <div className="admin-config-notice" role="status">{message}</div> : null}<div className="admin-detail-grid"><section className="admin-panel"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Onboarding</p><h2>Business profile</h2></div></div><dl className="admin-detail-list"><div><dt>Legal name</dt><dd>{vendor.legalName || 'Not provided'}</dd></div><div><dt>Contact</dt><dd>{vendor.contactName || 'Not provided'}{vendor.contactPhone ? ` · ${vendor.contactPhone}` : ''}</dd></div><div><dt>Business type</dt><dd>{vendor.businessType || 'Not provided'}</dd></div><div><dt>Onboarding status</dt><dd>{label(vendor.onboardingStatus || 'not started')}</dd></div><div><dt>Last updated</dt><dd>{formatDate(vendor.updatedAt)}</dd></div></dl></section><section className="admin-panel"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Vendor users</p><h2>{vendor.users.length} users</h2></div></div>{vendor.users.length ? <div className="admin-list">{vendor.users.map((user) => <div className="admin-list-row" key={user.id}><div><strong>{user.name || user.email}</strong><span>{user.email} · {user.role}</span></div><time dateTime={user.createdAt}>{formatDate(user.createdAt)}</time></div>)}</div> : <p className="admin-empty">No linked vendor users found.</p>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Catalog</p><h2>{vendor.products.length} products</h2></div><Link href="/admin/products" className="admin-text-link">Product area</Link></div>{vendor.products.length ? <div className="admin-list">{vendor.products.map((product) => <div className="admin-list-row" key={product.id}><div><strong>{product.name}</strong><span>{product.sku} · {label(product.status)} · {label(product.lifecycleStatus)}</span></div><time dateTime={product.updatedAt}>{formatDate(product.updatedAt)}</time></div>)}</div> : <p className="admin-empty">No products found. Product approval remains outside Phase 2.</p>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Documents</p><h2>{vendor.documents.length} documents</h2></div></div>{vendor.documents.length ? <div className="admin-list">{vendor.documents.map((document) => <div className="admin-list-row" key={document.id}><div><strong>{document.name}</strong><span>{label(document.type)} · {label(document.status)}</span></div><time dateTime={document.uploadedAt}>{formatDate(document.uploadedAt)}</time></div>)}</div> : <p className="admin-empty">No vendor documents found.</p>}</section><section className="admin-panel admin-panel-wide"><div className="admin-panel-heading"><div><p className="admin-eyebrow">Audit history</p><h2>Vendor activity</h2></div><span className="admin-data-note">Append only</span></div>{vendor.activity.length ? <div className="admin-list admin-list-two-col">{vendor.activity.map((item) => <div className="admin-list-row" key={item.id}><div><strong>{label(item.action)}</strong><span>{item.detail} · Actor {item.actorId.slice(0, 8)}</span></div><time dateTime={item.createdAt}>{formatDate(item.createdAt)}</time></div>)}</div> : <p className="admin-empty">No administrative activity recorded yet.</p>}</section></div></div>{pending ? <div className="admin-dialog-backdrop"><section className="admin-dialog" role="dialog" aria-modal="true" aria-labelledby="status-title"><p className="admin-eyebrow">Confirm status change</p><h2 id="status-title">{pending.label} this vendor?</h2><p>{pending.consequence} This action is recorded in audit history.</p><label>Reason or note (optional)<textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={3} /></label><div className="admin-dialog-actions"><button type="button" className="admin-button admin-button-secondary" onClick={() => setPending(null)}>Cancel</button><button type="button" className="admin-button admin-button-primary" onClick={() => void changeStatus()}>Confirm {pending.label.toLowerCase()}</button></div></section></div> : null}</main>
}
